from pathlib import Path
P=Path("public")
def replace(file,old,new):
 f=P/file;s=f.read_text()
 if new in s: print("Already applied",file);return
 if s.count(old)!=1: raise RuntimeError(f"{file}: expected one anchor, found {s.count(old)}. Stop.")
 f.write_text(s.replace(old,new,1));print("Updated",file)
